import numpy as np
from PIL import Image
from scipy.ndimage import label, find_objects
im=np.array(Image.open('first_frame.png').convert('RGB'))
g=im.mean(2)
for t in [25,35,45,55,70,90]:
 L,n=label(g<t)
 parts=[]
 for i,sl in enumerate(find_objects(L),1):
  if sl:
   area=(L[sl]==i).sum()
   if area>20:
    parts.append((area,(sl[1].start,sl[0].start,sl[1].stop-1,sl[0].stop-1)))
 print('\\nTHR',t,'components',len(parts))
 print(sorted(parts,reverse=True)[:20])
# row runs for central dark object
for t in [25,35,45,55]:
 print('\\nTHR',t,'row extents central comp-ish')
 m=g<t
 for y in range(50,270,5):
  xs=np.where(m[y,150:420])[0]+150
  # runs >=3
  runs=[]
  if len(xs):
   a=xs[0]; p=xs[0]
   for x in xs[1:]:
    if x>p+1:
     if p-a>=2:runs.append((a,p))
     a=x
    p=x
   if p-a>=2:runs.append((a,p))
  if runs: print(f'{y:3}:',runs)
